class StopWatch
  {
    public:
      /** \brief Constructor. */
      StopWatch () = default;

      /** \brief Retrieve the time in milliseconds spent since the last call to \a reset(). */
      inline double
      getTime () const
      {
        auto end_time = std::chrono::steady_clock::now();
        return std::chrono::duration<double, std::ratio<1, 1000>>(end_time - start_time_).count();
      }

      /** \brief Retrieve the time in seconds spent since the last call to \a reset(). */
      inline double
      getTimeSeconds () const
      {
        return (getTime () * 0.001);
      }

      /** \brief Reset the stopwatch to 0. */
      inline void
      reset ()
      {
        start_time_ = std::chrono::steady_clock::now();
      }

    protected:
      std::chrono::time_point<std::chrono::steady_clock> start_time_ = std::chrono::steady_clock::now();
  };

class ScopeTime : public StopWatch
  {
    public:
      inline ScopeTime (const std::string &title = "") : 
        title_ (title)
      {
      }

      inline ~ScopeTime ()
      {
        double val = this->getTime ();
        std::cerr << title_ << " took " << val << "ms.\n";
      }

    private:
      std::string title_;
  };

class EventFrequency
  {

    public:

      /** \brief Constructor.
        *
        * \param[in] window_size number of most recent events that are
        * considered in frequency estimation (default: 30) */
      EventFrequency (std::size_t window_size = 30)
      : window_size_ (window_size)
      {
        stop_watch_.reset ();
      }

      /** \brief Notifies the class that the event occurred. */
      void event ()
      {
        event_time_queue_.push (stop_watch_.getTimeSeconds ());
        if (event_time_queue_.size () > window_size_)
          event_time_queue_.pop ();
      }

      /** \brief Retrieve the estimated frequency. */
      double
      getFrequency () const
      {
        if (event_time_queue_.size () < 2)
          return (0.0);
        return ((event_time_queue_.size () - 1) /
                (event_time_queue_.back () - event_time_queue_.front ()));
      }

      /** \brief Reset frequency computation. */
      void reset ()
      {
        stop_watch_.reset ();
        event_time_queue_ = std::queue<double> ();
      }

    private:

      pcl::StopWatch stop_watch_;
      std::queue<double> event_time_queue_;
      const std::size_t window_size_;

  };

class PCL_EXPORTS PosesFromMatches
  {
    public:
      // =====STRUCTS=====
      //! Parameters used in this class
      struct PCL_EXPORTS Parameters
      {
        float max_correspondence_distance_error = 0.2f;  // As a fraction
      };

      //! A result of the pose estimation process
      struct PoseEstimate
      {
        Eigen::Affine3f transformation = Eigen::Affine3f::Identity ();   //!< The estimated transformation between the two coordinate systems
        float score = 0;                         //!< An estimate in [0,1], how good the estimated pose is 
        Indices correspondence_indices;  //!< The indices of the used correspondences

        struct IsBetter 
        {
          bool operator()(const PoseEstimate& pe1, const PoseEstimate& pe2) const { return pe1.score>pe2.score;}
        };
        public:
          PCL_MAKE_ALIGNED_OPERATOR_NEW
      };

      // =====TYPEDEFS=====
      using PoseEstimatesVector = std::vector<PoseEstimate, Eigen::aligned_allocator<PoseEstimate> >;

      // =====STATIC METHODS=====

      // =====PUBLIC METHODS=====
      /** Use single 6DOF correspondences to estimate transformations between the coordinate systems.
       *  Use max_no_of_results=-1 to use all.
       *  It is assumed, that the correspondences are sorted from good to bad. */
      void 
      estimatePosesUsing1Correspondence (
          const PointCorrespondences6DVector& correspondences,
          int max_no_of_results, PoseEstimatesVector& pose_estimates) const;

      /** Use pairs of 6DOF correspondences to estimate transformations between the coordinate systems.
       *  It is assumed, that the correspondences are sorted from good to bad. */
      void 
      estimatePosesUsing2Correspondences (
          const PointCorrespondences6DVector& correspondences,
          int max_no_of_tested_combinations, int max_no_of_results,
          PoseEstimatesVector& pose_estimates) const;

      /** Use triples of 6DOF correspondences to estimate transformations between the coordinate systems.
       *  It is assumed, that the correspondences are sorted from good to bad. */
      void 
      estimatePosesUsing3Correspondences (
          const PointCorrespondences6DVector& correspondences,
          int max_no_of_tested_combinations, int max_no_of_results,
          PoseEstimatesVector& pose_estimates) const;

      /// Get a reference to the parameters struct
      Parameters& 
      getParameters () { return parameters_; }

    protected:
      // =====PROTECTED MEMBER VARIABLES=====
      Parameters parameters_;

  };

