// Harness for: inline void pcl::geometry::project(const Eigen::Vector3f& point,
//                                                const Eigen::Vector3f& plane_origin,
//                                                const Eigen::Vector3f& plane_normal,
//                                                Eigen::Vector3f& projected)
{
  // Obtain a compile-time sized pool of random seeds. The FUZZ_PARAM array form
  // returns a pointer-to-array type, not a pointer to first element.
  const unsigned int (*seeds)[12] = FUZZ_PARAM(unsigned int[12]);
  const auto &s = *seeds;

  // Map an unsigned int to a bounded finite float in [-1000, 1000]
  auto to_bounded = [](unsigned int v)->float {
    int span = static_cast<int>(v % 2000001u) - 1000000;
    return static_cast<float>(span) / 1000.0f;
  };

  Eigen::Vector3f point(to_bounded(s[0]), to_bounded(s[1]), to_bounded(s[2]));
  Eigen::Vector3f origin(to_bounded(s[3]), to_bounded(s[4]), to_bounded(s[5]));
  Eigen::Vector3f n_raw(to_bounded(s[6]), to_bounded(s[7]), to_bounded(s[8]));

  // Enforce plane_normal unit-length and non-degenerate per API requirements
  float n_norm = n_raw.norm();
  if (!(n_norm > 1e-6f) || !std::isfinite(n_norm)) {
    // Fallback: construct an alternate non-degenerate vector
    Eigen::Vector3f alt(to_bounded(s[9]) + 1.0f, to_bounded(s[10]) + 2.0f, to_bounded(s[11]) + 3.0f);
    n_raw = alt;
    n_norm = n_raw.norm();
    if (!(n_norm > 1e-6f) || !std::isfinite(n_norm)) {
      // Cannot satisfy precondition
      FUZZ_BAIL();
    }
  }
  Eigen::Vector3f n = n_raw / n_norm; // normalized unit normal

  // Ensure inputs are finite as required
  if (!point.allFinite() || !origin.allFinite() || !n.allFinite()) {
    FUZZ_BAIL();
  }

  // Call target
  Eigen::Vector3f projected;
  pcl::geometry::project(point, origin, n, projected);

  // Property: projected lies on the plane: n dot (proj - origin) ~= 0
  float plane_eval = n.dot(projected - origin);
  FUZZ_ASSERT(std::isfinite(plane_eval), "Non-finite plane evaluation");
  FUZZ_ASSERT(std::fabs(plane_eval) < 1e-3f, "Projection not on plane within tolerance");
}

// Harness for: inline Eigen::Vector3f pcl::geometry::projectedAsUnitVector(
//               const Eigen::Vector3f& point,
//               const Eigen::Vector3f& plane_origin,
//               const Eigen::Vector3f& plane_normal)
{
  // Seed array for reproducible randoms
  const unsigned int (*seeds)[12] = FUZZ_PARAM(unsigned int[12]);
  const auto &s = *seeds;

  auto to_bounded = [](unsigned int v)->float {
    int span = static_cast<int>(v % 2000001u) - 1000000;
    return static_cast<float>(span) / 1000.0f;
  };

  // Build plane origin and a safe, unit-length normal
  Eigen::Vector3f origin(to_bounded(s[0]), to_bounded(s[1]), to_bounded(s[2]));
  Eigen::Vector3f n_raw(to_bounded(s[3]), to_bounded(s[4]), to_bounded(s[5]));
  float n_norm = n_raw.norm();
  if (!(n_norm > 1e-6f) || !std::isfinite(n_norm)) {
    // Fallback normal
    Eigen::Vector3f alt(to_bounded(s[6]) + 2.0f, to_bounded(s[7]) + 1.0f, to_bounded(s[8]) + 3.0f);
    n_raw = alt; n_norm = n_raw.norm();
    if (!(n_norm > 1e-6f) || !std::isfinite(n_norm)) { FUZZ_BAIL(); }
  }
  Eigen::Vector3f n = n_raw / n_norm;

  if (!origin.allFinite() || !n.allFinite()) { FUZZ_BAIL(); }

  // Construct a point guaranteed to have a non-zero tangential projection onto the plane.
  // Strategy: create a random vector r, remove its normal component to get v in plane.
  Eigen::Vector3f r(to_bounded(s[9]), to_bounded(s[10]), to_bounded(s[11]));
  Eigen::Vector3f v = r - n * n.dot(r); // tangential component
  if (v.norm() <= 1e-6f || !v.allFinite()) {
    // If nearly parallel to normal or degenerate, build an explicit orthogonal direction via cross product
    Eigen::Vector3f e1(1.0f, 0.0f, 0.0f);
    Eigen::Vector3f e2(0.0f, 1.0f, 0.0f);
    v = n.cross((std::fabs(n.dot(e1)) < 0.9f) ? e1 : e2);
  }
  // Scale v to a reasonable magnitude to avoid underflow
  float scale = 1.0f + std::fmod(std::fabs(to_bounded(s[9])) + 0.1f, 10.0f);
  v *= scale;
  Eigen::Vector3f point = origin + v; // ensures projected point != origin

  if (!point.allFinite()) { FUZZ_BAIL(); }

  // Call target
  Eigen::Vector3f dir = pcl::geometry::projectedAsUnitVector(point, origin, n);

  // Validations: unit length and orthogonal to normal (lies in plane)
  float dir_norm = dir.norm();
  FUZZ_ASSERT(std::isfinite(dir_norm), "Non-finite output norm");
  FUZZ_ASSERT(std::fabs(dir_norm - 1.0f) < 1e-3f, "Output vector not unit length");
  float dotp = n.dot(dir);
  FUZZ_ASSERT(std::isfinite(dotp), "Non-finite dot product");
  FUZZ_ASSERT(std::fabs(dotp) < 1e-3f, "Output direction not in plane (not orthogonal to normal)");
}

